import java.util.List;
import java.util.ArrayList;
import org.eclipse.core.filesystem.IFileStore;
import org.eclipse.core.filesystem.IFileInfo;

// Dummy classes for example, as in original Eclipse JDT UI context
interface IFileStore {
    IFileInfo fetchInfo();
    String getName();
}
interface IFileInfo {
    boolean isDirectory();
    boolean exists();
}

class DummyFileStore implements IFileStore {
    String name;
    boolean directory;
    boolean exists;
    public DummyFileStore(String name, boolean isDir, boolean exists) {
        this.name = name;
        this.directory = isDir;
        this.exists = exists;
    }
    @Override public IFileInfo fetchInfo() { return new DummyFileInfo(directory, exists); }
    @Override public String getName() { return name; }
}
class DummyFileInfo implements IFileInfo {
    boolean directory;
    boolean exists;
    public DummyFileInfo(boolean isDir, boolean exists) {
        this.directory = isDir;
        this.exists = exists;
    }
    @Override public boolean isDirectory() { return directory; }
    @Override public boolean exists() { return exists; }
}

public class MyClass {
    private List<IFileStore> fOrginalFolders = new ArrayList<>();

    public void processChildren(IFileStore[] children) {
        for (int i= 0; i < children.length; i++) {
            IFileStore child= children[i];
            IFileInfo info= child.fetchInfo();
            if (info.isDirectory() && info.exists() && !fOrginalFolders.contains(child.getName())) {
                fOrginalFolders.add(child);
            }
        }
    }
}

